create table media_asset (id bigint auto_increment primary key, department_id bigint not null, name varchar(160) not null, kind varchar(20) not null, mime varchar(60) not null, sha256 varchar(64) not null, blob_name varchar(80) not null, bytes bigint not null, width int not null, height int not null, duration double not null, enabled boolean not null, version bigint not null, created_at timestamp(6) not null, foreign key(department_id) references department(id));
create table screen_group (id bigint auto_increment primary key, department_id bigint not null, name varchar(120) not null, enabled boolean not null, version bigint not null, foreign key(department_id) references department(id));
create table playlist (id bigint auto_increment primary key,category_id bigint not null,foreign key(category_id) references dictionary_entry(id),department_id bigint not null,name varchar(160) not null,name_en varchar(160) not null,orientation varchar(20) not null,fit varchar(20) not null,background varchar(7) not null,version bigint not null,foreign key(department_id) references department(id));
create table published_release (id varchar(36) primary key, department_id bigint not null, playlist_id bigint not null, name varchar(160) not null, snapshot longtext not null, created_at timestamp(6) not null, actor varchar(80) not null,request_hash varchar(64) not null, foreign key(department_id) references department(id), foreign key(playlist_id) references playlist(id));
create table screen (id bigint auto_increment primary key, department_id bigint not null, group_id bigint, name varchar(120) not null, token_hash varchar(64), enabled boolean not null, version bigint not null, baseline_release varchar(36), last_seen timestamp(6), applied_release varchar(36), player_state varchar(30), player_error varchar(120), foreign key(department_id) references department(id), foreign key(group_id) references screen_group(id), foreign key(baseline_release) references published_release(id));
create table playlist_item (id bigint auto_increment primary key, playlist_id bigint not null, asset_id bigint, position int not null, text varchar(4000), seconds int not null, color varchar(7) not null, foreign key(playlist_id) references playlist(id), foreign key(asset_id) references media_asset(id));
create table release_asset (id bigint auto_increment primary key, release_id varchar(36) not null, asset_id bigint not null, foreign key(release_id) references published_release(id), foreign key(asset_id) references media_asset(id));
create table delivery (id bigint auto_increment primary key, screen_id bigint not null, release_id varchar(36) not null, foreign key(screen_id) references screen(id), foreign key(release_id) references published_release(id));
create table schedule (id bigint auto_increment primary key, department_id bigint not null, screen_id bigint not null, release_id varchar(36) not null, starts_at timestamp(6) not null, ends_at timestamp(6) not null, cancelled boolean not null, version bigint not null, foreign key(department_id) references department(id), foreign key(screen_id) references screen(id), foreign key(release_id) references published_release(id));
create unique index uq_item_position on playlist_item(playlist_id,position);
create unique index uq_delivery on delivery(screen_id,release_id);
create unique index uq_release_asset on release_asset(release_id,asset_id);
create unique index uq_device_token on screen(token_hash);
create index ix_schedule on schedule(screen_id,cancelled,starts_at,ends_at);
